using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public class StepResult
{
    public double Lo { get; set; }
    public double Hi { get; set; }
    public long PartialCount { get; set; }
}

public class BisectionStep : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        const int M = 16777216;
        const long K = 5000000;
        double lo = 0.0, hi = 1.0;
        if (input.PreviousLayerResults != null && input.PreviousLayerResults.Count > 0)
        {
            long total = 0;
            bool found = false;
            foreach (string json in input.GetPreviousOutputs())
            {
                if (json == null) continue;
                StepResult r = JsonSerializer.Deserialize<StepResult>(json);
                if (r == null) continue;
                if (!found) { lo = r.Lo; hi = r.Hi; found = true; }
                total += r.PartialCount;
            }
            if (!found) return Task.FromResult(AgentLayerResult.Error("No successful outputs from previous step"));
            if (total >= K) hi = (lo + hi) / 2.0;
            else lo = (lo + hi) / 2.0;
        }
        double mid = (lo + hi) / 2.0;
        long count = 0;
        for (int i = input.WorkerIndex + 1; i <= M; i += input.TotalWorkers)
        {
            if ((i & 65535) == 0) ct.ThrowIfCancellationRequested();
            ulong z = unchecked((ulong)i * 0x9E3779B97F4A7C15UL);
            z = unchecked((z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL);
            z = unchecked((z ^ (z >> 27)) * 0x94D049BB133111EBUL);
            z ^= z >> 31;
            double v = (double)(z % 2147483647UL) / 2147483647.0;
            if (v <= mid) count++;
        }
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new StepResult { Lo = lo, Hi = hi, PartialCount = count })));
    }
}

public class FinalMidpoint : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        const long K = 5000000;
        double lo = 0.0, hi = 1.0;
        long total = 0;
        bool found = false;
        foreach (string json in input.GetPreviousOutputs())
        {
            if (json == null) continue;
            StepResult r = JsonSerializer.Deserialize<StepResult>(json);
            if (r == null) continue;
            if (!found) { lo = r.Lo; hi = r.Hi; found = true; }
            total += r.PartialCount;
        }
        if (!found) return Task.FromResult(AgentLayerResult.Error("No successful outputs from step 32"));
        if (total >= K) hi = (lo + hi) / 2.0;
        else lo = (lo + hi) / 2.0;
        double midpoint = (lo + hi) / 2.0;
        string formatted = midpoint.ToString("G17", CultureInfo.InvariantCulture);
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new { midpoint = formatted, lo = lo.ToString("G17", CultureInfo.InvariantCulture), hi = hi.ToString("G17", CultureInfo.InvariantCulture), countAtStep32Mid = total })));
    }
}

